const root=document.querySelector('[data-commerce-component="invoice-details"]');
const request=root.querySelector('[data-invoice-request]');
const fields=root.querySelector('[data-invoice-fields]');
const legalName=root.querySelector('#invoice-legal-name');
request.addEventListener('change',()=>{
  const requested=request.checked;
  root.dataset.invoiceRequested=String(requested);
  fields.hidden=!requested;
  legalName.required=requested;
  if(!requested)legalName.setCustomValidity('');
});
legalName.addEventListener('input',()=>legalName.setCustomValidity(''));
legalName.addEventListener('invalid',()=>legalName.setCustomValidity('Enter a legal name when requesting a business invoice.'));
